class Solution {
    private int count;

    public int totalNQueens(int n) {
        count = 0;
        place(new int[n], 0);
        return count;
    }

    private void place(int[] queenColumn, int row) {
        if (row == queenColumn.length) {
            count++;
            return;
        }
        for (int column = 0; column < queenColumn.length; column++) {
            boolean safe = true;
            for (int earlierRow = 0; earlierRow < row; earlierRow++) {
                int earlierColumn = queenColumn[earlierRow];
                if (earlierColumn == column || Math.abs(earlierColumn - column) == row - earlierRow) {
                    safe = false;
                    break;
                }
            }
            if (safe) {
                queenColumn[row] = column;
                place(queenColumn, row + 1);
            }
        }
    }
}

