class Solution {
    private int count;
    private boolean[] columns;
    private boolean[] descendingDiagonals;
    private boolean[] ascendingDiagonals;

    public int totalNQueens(int n) {
        count = 0;
        columns = new boolean[n];
        descendingDiagonals = new boolean[2 * n - 1];
        ascendingDiagonals = new boolean[2 * n - 1];
        place(0, n);
        return count;
    }

    private void place(int row, int n) {
        if (row == n) {
            count++;
            return;
        }
        for (int column = 0; column < n; column++) {
            int descending = row - column + n - 1;
            int ascending = row + column;
            if (columns[column] || descendingDiagonals[descending] || ascendingDiagonals[ascending]) {
                continue;
            }
            columns[column] = true;
            descendingDiagonals[descending] = true;
            ascendingDiagonals[ascending] = true;
            place(row + 1, n);
            columns[column] = false;
            descendingDiagonals[descending] = false;
            ascendingDiagonals[ascending] = false;
        }
    }
}
